// =============================================================================
// 场景：每次产线启动生成新 batch session GUID，写入 MES 数据库 UNIQUEIDENTIFIER
//       字段；MES 用此 ID 关联本批次的所有工序记录。数据库期望无花括号格式。
// 价值：RFC 4122 标准格式开箱兼容 MES / 数据库；不必自创格式或写转换器。
// 验证步骤：
//   1. 登录后 gBatchSessionId 各字段全 0，sBatchSessionId = ''。
//   2. 在线设置 gBatchSessionId.Data1 := 16#ABCDEF01; .Data2 := 16#2345;
//      .Data3 := 16#6789; .Data4 := [16#AB,16#CD,16#EF,16#01,16#23,16#45,16#67,16#89];
//   3. 写 bFormatRequest := TRUE。
//   4. 观察 sBatchSessionId = 'ABCDEF01-2345-6789-ABCD-EF0123456789'，长度 36。
//   5. 把 g 重置全 0，触发，得 '00000000-0000-0000-0000-000000000000'——空 GUID 特殊形态。
//   6. 数据库导入：可直接 INSERT INTO BatchLog (BatchId, ...) VALUES (sBatchSessionId, ...)。
// =============================================================================

IF bFormatRequest THEN
    // 单次调用：永远成功；目标至少 STRING(36)
    sBatchSessionId := GUID_TO_STRING(stIn := gBatchSessionId);
    bFormatRequest := FALSE;
END_IF;
